sys_script_include.script:
var BillingUtils = Class.create();
BillingUtils.prototype = {
    initialize: function() {},
    getTotalBillingAmount: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patient_id', id);
        bill.query();
        if (bill.next()) {
            return bill;
        }

    },

    isBillingOverdue: function(id) {
        var bill = new GlideRecord('u_billing');
        if (bill.get(id)) {
            if (bill.u_status == 'overdue') {
                return true;
            }
        }
        return false;
    },

    getBillingByID: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('number', id);
        bill.query();
        if(bill.next())
		{
			return bill;
		}
		else{
			return "No";
		}
    },

    getBillingByPatientID: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patient_id', id);
        bill.query();
        return bill;
    },

    type: 'BillingUtils'
};
